window.ScripturaLexicons.BDAG_PART_0333 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-01\" data-source=\"BDAG\" data-search=\"στρατιωτικός, ή, όν adjetivo militar; de soldados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατιωτικός, ή, όν</td><td>adjetivo</td><td>militar; de soldados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-02\" data-source=\"BDAG\" data-search=\"στρατολογέω verbo reunir um exército; alistar soldados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατολογέω</td><td>verbo</td><td>reunir um exército; alistar soldados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-03\" data-source=\"BDAG\" data-search=\"στρατοπεδάρχης substantivo masculino comandante militar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατοπεδάρχης</td><td>substantivo masculino</td><td>comandante militar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-04\" data-source=\"BDAG\" data-search=\"στρατόπεδον, ου, τό substantivo neutro acampamento; exército; legião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρατόπεδον, ου, τό</td><td>substantivo neutro</td><td>acampamento; exército; legião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-05\" data-source=\"BDAG\" data-search=\"στρεβλός, ή, όν adjetivo tortuoso; perverso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρεβλός, ή, όν</td><td>adjetivo</td><td>tortuoso; perverso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-06\" data-source=\"BDAG\" data-search=\"στρεβλόω verbo atormentar; distorcer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρεβλόω</td><td>verbo</td><td>atormentar; distorcer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-07\" data-source=\"BDAG\" data-search=\"στρέφω verbo voltar; devolver; transformar; mudar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρέφω</td><td>verbo</td><td>voltar; devolver; transformar; mudar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-08\" data-source=\"BDAG\" data-search=\"στρηνιάω verbo viver no luxo; viver sensualmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρηνιάω</td><td>verbo</td><td>viver no luxo; viver sensualmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-09\" data-source=\"BDAG\" data-search=\"στρῆνος, ους, τό substantivo neutro sensualidade; luxo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρῆνος, ους, τό</td><td>substantivo neutro</td><td>sensualidade; luxo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-10\" data-source=\"BDAG\" data-search=\"στρογγύλος, η, ον adjetivo redondo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρογγύλος, η, ον</td><td>adjetivo</td><td>redondo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-11\" data-source=\"BDAG\" data-search=\"στρουθίον, ου, τό substantivo neutro pardal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρουθίον, ου, τό</td><td>substantivo neutro</td><td>pardal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-12\" data-source=\"BDAG\" data-search=\"στρουθός, ου, ὁ substantivo masculino pardal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρουθός, ου, ὁ</td><td>substantivo masculino</td><td>pardal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-13\" data-source=\"BDAG\" data-search=\"στρωννύω/στρώννυμι verbo estender; mobiliar; selar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στρωννύω/στρώννυμι</td><td>verbo</td><td>estender; mobiliar; selar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-14\" data-source=\"BDAG\" data-search=\"στυγητός, ή, όν adjetivo odioso; desprezível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στυγητός, ή, όν</td><td>adjetivo</td><td>odioso; desprezível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-15\" data-source=\"BDAG\" data-search=\"στυγνάζω verbo ficar estarrecido; tornar-se sombrio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στυγνάζω</td><td>verbo</td><td>ficar estarrecido; tornar-se sombrio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-16\" data-source=\"BDAG\" data-search=\"στυγνός, ή, όν adjetivo sombrio; triste BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στυγνός, ή, όν</td><td>adjetivo</td><td>sombrio; triste</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-17\" data-source=\"BDAG\" data-search=\"στῦλος, ου, ὁ substantivo masculino pilar; coluna; sustentáculo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στῦλος, ου, ὁ</td><td>substantivo masculino</td><td>pilar; coluna; sustentáculo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-18\" data-source=\"BDAG\" data-search=\"στύραξ, ακος, ὁ substantivo masculino ponta de lança; haste; lança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στύραξ, ακος, ὁ</td><td>substantivo masculino</td><td>ponta de lança; haste; lança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-19\" data-source=\"BDAG\" data-search=\"Στωϊκός remissão ver Στοϊκός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Στωϊκός</td><td>remissão</td><td>ver Στοϊκός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0333-20\" data-source=\"BDAG\" data-search=\"σύ pronome pessoal tu; vós BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύ</td><td>pronome pessoal</td><td>tu; vós</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0333-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατιωτικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατιωτικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">στρατιώτης</span>; X., Pla. et al.; inscrições, papiros, EpArist; Philo, Virt. 23; Jos., Bell. 1, 340) pertencente a soldados ou composto de soldados <span class=\"greek\">στρατιωτικὸν</span> <span class=\"greek\">τάγμα</span> um destacamento de soldados IRo 5:1.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατολογέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατολογέω</span> (<span class=\"greek\">στρατός</span> ‘exército, hoste’, <span class=\"greek\">λέγω</span>) 1 aoristo <span class=\"greek\">ἐστρατολόγησα</span> reunir um exército, alistar soldados (Diod S 12, 67, 5; 14, 54, 6; Dionys. Hal. 11, 24; Plut., Caesar 724 [35, 1]; Jos., Bell. 5, 380) <span class=\"greek\">ὁ</span> <span class=\"greek\">στρατολογήσας</span> aquele que (o) alistou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:4</a>.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατοπεδάρχης</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατοπεδάρχης</span> (<span class=\"greek\">στρατόπεδον</span>, <span class=\"greek\">ἀρχή</span>; Dionys. Hal. 10, 36; Lucian, Hist. 22; Vett. Val. 76, 13; Jos., Bell. 2, 531; 6, 238; OGI 605, 3; BGU 1822, 13 [I a.C.]; Mitt-Wilck. II/2, 87, 5 [II d.C.]) assim o texto recebido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:16</a> (v. Tdf.) ou <span class=\"greek\">στρατοπέδαρχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> comandante militar, comandante de um acampamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:16</a> variante de leitura. Sobre o assunto v. Mommsen e Harnack, SBBerlAk 1895, 491ff; Zahn, Einl.3 I 392ff; AWikenhauser, Die AG 1921, 358f; Pauly-W. IV 1896ff; Haenchen ad loc.; Mason 87; HTajra, The Trial of St. Paul ’89, 177.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρατόπεδον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρατόπεδον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aeschyl., Hdt. et al.; inscrições, LXX, Philo, Joseph.) literalmente ‘acampamento’ (Jos., Vi. 398), depois ‘corpo de tropas, exército’ (Eur., Hdt. et al.; inscrições, LXX; EpArist 20; Jos., Ant. 14, 271), até mesmo especificamente legião (Polyb. 1, 16, 2; 1, 26, 6; 6, 20ff; 27ff; BGU 362 XI, 15 [III d.C.].—Hahn 46) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:20</a>; Mason 87.—B. 1377. DELG s.v. <span class=\"greek\">στρατό</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρεβλός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρεβλός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Aristoph., Hippocr. et al.; LXX; usado p. ex. de uma testa franzida ou de torções e voltas em competição atlética) em nossa literatura somente em sentido figurado, tortuoso, perverso, do caminho da injustiça Hm 6, 1, 2f. De pessoas (Eupolis Com. [V a.C.] 182) 1 Cl 46:3 (Ps 17:27).—B. 897. DELG. Cf. <span class=\"greek\">στρεβλόω</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρεβλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρεβλόω</span> (<span class=\"greek\">στρέφω</span>, cf. o artigo anterior) imperativo da 2 pessoa do singular <span class=\"greek\">στρέβλου</span> (Hdt., Aristoph. et al.; papiros, LXX) originalmente ‘torcer, esticar’ de cabos, depois em vários sentidos de manipular membros deslocados a fim de recolocá-los no lugar e de empregar instrumentos de tortura no decurso de investigações (v. p. ex. BGU 195, 13 [II d.C.]; 4 Macc; Jos., Bell. 7, 373); em nossa literatura somente em sentido figurado (cf. 2 Km 22:27 de pessoas perversas)</p>\n<p class=\"entry-text\">① causar dor interior, torturar, atormentar (Diod S 16, 61, 3 atormentado pela ansiedade) <span class=\"greek\">μὴ</span> <span class=\"greek\">στρέβλου</span> <span class=\"greek\">σεαυτόν</span> não te aflijas (com a solução de um enigma, como Vi. Aesopi W 78 P.) Hs 9, 2, 7.</p>\n<p class=\"entry-text\">② distorcer uma afirmação de modo que resulte um sentido falso, torcer, deturpar (2 Km 22:27) <span class=\"greek\">τὶ</span> algo (Numenius de Apameia, <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἀκαδημαϊκῶν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Πλάτωνα</span> <span class=\"greek\">διαστάσεως</span> 1, 1 ed. KGuthrie [1917] p. 63) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:16</a>.—DELG s.v. <span class=\"greek\">στρεβλό</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρέφω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρέφω</span> futuro <span class=\"greek\">στρέψω</span> LXX; 1 aoristo <span class=\"greek\">ἔστρεψα</span>. Passivo: 2 futuro <span class=\"greek\">στραφήσομαι</span> LXX; 2 aoristo <span class=\"greek\">ἐστράφν</span> (Hom. +).</p>\n<p class=\"entry-text\">① mudar a posição de algo em relação a outra coisa mediante uma volta</p>\n<p class=\"entry-text\">ⓐ voltar (SibOr 5, 497 <span class=\"greek\">στ</span>. <span class=\"greek\">ψυχάς</span>) <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> algo para alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:39</a>; D 1:4.—Assim talvez também em sentido não literal <span class=\"greek\">ἔστρεψεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> Deus voltou os israelitas para os corpos celestes, de modo que os servissem como seus deuses <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:42</a> (v. 3 Km 18:37 <span class=\"greek\">σὺ</span> <span class=\"greek\">ἔστρεψας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">ὀπίσω</span>. Mas v. 4 abaixo).</p>\n<p class=\"entry-text\">ⓑ voltar-se, virar-se para, passivo com valor ativo</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. literalmente <span class=\"greek\">στραφείς</span> seguido de verbo finito, voltou-se e … (X., Cyr. 3, 3, 63; TestAbr B 12 p. 116, 14 [Stone p. 80]). A finalidade de voltar-se pode ser atacar alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:6</a>, ou o desejo de ver alguém ou falar-lhe 9:22 (cf. Mitt-Wilck. I/2, 20 I, 6 <span class=\"greek\">στραφεὶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱδὼν</span> <span class=\"greek\">Ἡλιόδωρον</span> <span class=\"greek\">εἶπεν</span>); 16:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:9</a>; 9:55; 14:25; 22:61; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:38</a>; 20:16; MPol 5:2. Verbo finito em lugar do particípio (ApcMos 19) <span class=\"greek\">ἐστράφη</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">εἶδεν</span> GJs 15:1; 17:2ab. <span class=\"greek\">στρ</span>. <span class=\"greek\">πρός</span> com acusativo, voltar-se para ou em direção a (escólio a Nicander, Ther. 677 <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἥλιον</span> <span class=\"greek\">στρέφεσθαι</span> do heliotrópio): <span class=\"greek\">στραφεὶς</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> seguido de verbo finito (TestJob 27:1; 29:3; ApcMos 23:25, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:44</a>; 10:22 variante de leitura, 23; 23:28. <span class=\"greek\">στρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπίσω</span> voltar-se para trás <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:14</a>; GJs 7:2 (cf. X., De Re Equ. 7, 12 <span class=\"greek\">στρέφεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δεξιά</span>).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. em sentido figurado de 1a, conjugando mudança de disposição mental e de direção <span class=\"greek\">στρεφόμεθα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> voltamo-nos para os gentios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:46</a>. <span class=\"greek\">ἐστράφησαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Αἴγυπτον</span> em seus corações voltaram ao Egito 7:39.</p>\n<p class=\"entry-text\">② levar algo de volta ao lugar anterior, trazer de volta, devolver <span class=\"greek\">τὶ</span> algo <span class=\"greek\">τὰ</span> <span class=\"greek\">τριάκοντα</span> <span class=\"greek\">ἀργύρια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:3</a></p>\n<p class=\"entry-text\">③ transformar algo em outra coisa, converter, mudar (Just., A I, 59, 1 <span class=\"greek\">ὕλην</span> de Deus) <span class=\"greek\">τὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> algo em algo <span class=\"greek\">ὕδατα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αἷμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:6</a> (cf. Ps 113:8; 29:12). Passivo, ser mudado, ser transformado (1 Km 10:6 <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">ἄλλον</span>) <span class=\"greek\">στραφήσονται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">λύκους</span> D 16:3a. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">στραφήσεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μῖσος</span> D 16:3b (cf. La 5:15; 1 Macc 1:39, 40).</p>\n<p class=\"entry-text\">④ afastar-se de modo a dissociar-se, voltar-se, intransitivo (X., An. 4, 3, 26; 32, Ages. 2, 3) assim talvez <span class=\"greek\">ἔστρεψεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> Deus se afastou deles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:42</a> (v. 1a acima).</p>\n<p class=\"entry-text\">⑤ experimentar uma mudança interior, voltar-se, mudar, passivo em sentido ativo. Para melhor: mudar de rumo, voltar-se (SibOr 3, 625) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:3</a> (JDupont, MBlack Festschr., ’69, 50–60); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40</a> (Is 6:9.—Field, Notes 99.—O termo inglês ‘conversão’ poderia sugerir uma mudança de uma convicção religiosa para outra, o que não ocorre nestas passagens). Para pior: voltar-se para algo mau, perverter-se D 11:2.—B. 666. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρηνιάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρηνιάω</span> (<span class=\"greek\">στρῆνος</span>) 1 aoristo <span class=\"greek\">ἐστρηνίασα</span> (Antiphanes em Athen. 3, 127d; Diphilus em Bekker, Anecdot. p. 113, 25; PMeyer 20, 23 [III d.C.]; Is 61:6 Sym.; POxy 2783, 24 de touros que correm desenfreadamente) viver no luxo, viver sensualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:7</a>. Com <span class=\"greek\">πορνεύειν</span> versículo 9.—DELG s.v. <span class=\"greek\">στρηνή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρῆνος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρῆνος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (em Nicostratus [IV a.C.]: Com. Att. Fgm. p. 230 n.º 42 Kock; Lycophron 438 e outras ocorrências; também 4 Km 19:28 em sentido diferente) sensualidade, luxo (Palladas [VI d.C.]: Anth. Pal. 7, 686) <span class=\"greek\">ἡ</span> <span class=\"greek\">δύναμις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στρήνους</span> (<span class=\"greek\">δύναμις</span> 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:3</a>.—DELG s.v. <span class=\"greek\">στρηνή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρογγύλος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρογγύλος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Aristoph., Thu., X., Pla.+; inscrições, papiros, LXX; Philo, Leg. All. 3, 57 [oposto a <span class=\"greek\">τετράγωνος</span>]) redondo, de pedras (X., De Re Equ. 4, 4; Cebes 18, 1 [oposto a <span class=\"greek\">τετρ</span>.]; JosAs 27:3) Hv 3, 2, 8; 3, 6, 5f; Hs 9, 6, 7f (oposto a <span class=\"greek\">τετρ</span>.); 9, 9, 1; 2 (oposto a <span class=\"greek\">τετρ</span>.); 9, 29, 4ab; 9, 30, 4.—B. 904. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρουθίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρουθίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aristot. et al.; LXX; PsSol 17:16; Jos., Bell. 5, 467) diminutivo de <span class=\"greek\">στρουθός</span>, pardal <span class=\"greek\">καλιά</span> <span class=\"greek\">στρουθίων</span> GJs 3:1 variante de leitura, um ninho de pardais; como exemplo de um artigo de pouco valor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:29</a>, 31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:6f</a>. (Vi. Aesopi G 26 P. é de interesse gramatical e formal, mas exprime um pensamento diferente: <span class=\"greek\">στρουθία</span> <span class=\"greek\">πολλοῦ</span> <span class=\"greek\">πωλεῖται</span>; numa restauração relativa a ‘aves que articulam palavras e alcançam alto preço’, v. a nota de Perry e p. 281 n.º 107.)—Dssm., LO 234f (LAE 272ff); HGrimme, BZ 23, ’35, 260–2. DELG s.v. <span class=\"greek\">στρουθό</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρουθός, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρουθός</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Sappho, Hdt. et al.) pardal GJs 3:1 variante de leitura, v. <span class=\"greek\">στρουθίον</span>.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στρωννύω/στρώννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στρωννύω</span>/<span class=\"greek\">στρώννυμι</span> imperfeito <span class=\"greek\">ἐστρώννυον</span>; futuro <span class=\"greek\">στρώσω</span> (JosAs 13:12 cód. A [p. 58, 10 Bat.]), 3 pessoa do plural -<span class=\"greek\">σουσιν</span> LXX; 1 aoristo <span class=\"greek\">ἔστρωσα</span>; perfeito <span class=\"greek\">ἔστρωκα</span> Pr 7:16. Passivo: perfeito, 3 pessoa do singular <span class=\"greek\">ἔστρωται</span> Job 17:13; particípio <span class=\"greek\">ἐστρωμένος</span> (sobre as duas formas da palavra: B-D-F §92; Rob. 318.—Quanto à palavra: Hom. [<span class=\"greek\">στορέννυμι</span>, <span class=\"greek\">στόρνυμι</span>], Aeschyl., X., Pla.; inscrições, papiros, LXX, TestAbr; JosAs 2:15 [também cód. A 13:12]; Joseph.; SibOr 5, 438)</p>\n<p class=\"entry-text\">① distribuir algo sobre uma superfície, estender <span class=\"greek\">τὶ</span> algo <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">κτλ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:8ab</a>; também <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:8</a> (quanto à ideia cf. 4 Km 9:13; Jos., Ant. 9, 111 <span class=\"greek\">ὑπεστρώννυεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱμάτιον</span>). <span class=\"greek\">χιτῶνας</span> <span class=\"greek\">χαμαί</span> Hs 9, 11, 7. <span class=\"greek\">στρῶσον</span> <span class=\"greek\">σεαυτῷ</span> (isto é, <span class=\"greek\">τὴν</span> <span class=\"greek\">κλίνην</span>; <span class=\"greek\">στρ</span>. é usado com este acusativo em Eur., Pla., e Nicol. Dam.: 90 Fgm. 44, 2 Jac.; Diod S 8, 32, 2; SIG 687, 16; 1022,1f <span class=\"greek\">τὴν</span> <span class=\"greek\">κλίνην</span> <span class=\"greek\">στρῶσαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Πλούτωνι</span>. Cf. Ezk 23:41; TestAbr B 5 p. 109, 17f [Stone p. 66], cf. A 4 p. 80, 17 [Stone p. 8] <span class=\"greek\">δύο</span> <span class=\"greek\">κλινάρια</span>; Jos., Ant. 7, 231 <span class=\"greek\">κλίνας</span> <span class=\"greek\">ἐστρωμένας</span>) arruma a tua própria cama <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:34</a>.—De um aposento, sem indicação do que é estendido ou colocado sobre uma superfície dentro dele: <span class=\"greek\">ἀνάγαιον</span> <span class=\"greek\">ἐστρωμένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:12</a> pode ser um aposento superior pavimentado (<span class=\"greek\">στρ</span>. tem esta acepção numa inscrição APF 2, 1903, 570 n.º 150. Assim Lutero et al.—Jos., Ant. 8, 134 <span class=\"greek\">ἐστρωμένος</span> significa ‘assoalhado’ ou ‘revestido de painéis’). Outros preferem 2a a seguir</p>\n<p class=\"entry-text\">② equipar algo com mobiliário apropriado</p>\n<p class=\"entry-text\">ⓐ mobiliar <span class=\"greek\">ἀνάγαιον</span> <span class=\"greek\">ἐστρωμένον</span> aposento superior mobiliado com tapetes ou leitos sobre os quais os convidados se reclinavam enquanto comiam (EKlostermann, ELohmeyer; Field, Notes 39; aproximadamente como Plut., Artox. 10 [22, 10]; Artem. 2, 57 códices. Também Diod S 21, 12, 4; IG II, 622 <span class=\"greek\">ἔστρωσεν</span> refere-se a um leito numa refeição; Dalman, Arbeit VII 185. As traduções inglesas geralmente preferem esta acepção.—PGM 1, 107 <span class=\"greek\">χώρημα</span> <span class=\"greek\">στρῶσαι</span> significa preparar um aposento para um banquete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:12</a>.</p>\n<p class=\"entry-text\">ⓑ selar um animal de montaria (L-S-J-M <span class=\"greek\">στόρνυμι</span> II) <span class=\"greek\">ἔστρωσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄνον</span> José selou seu jumento.—B. 573. DELG s.v. <span class=\"greek\">στόρνυμι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυγητός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στυγητός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Aeschyl., Prom. 592; POxy 433, 28; Philo, Dec. 131; Heliod. 5, 29, 4) odioso, desprezível <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:3</a> com <span class=\"greek\">μισέω</span>; 1 Cl 35:645; 1 Cl 35:6.—DELG s.v. <span class=\"greek\">στυγέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυγνάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στυγνάζω</span> (<span class=\"greek\">στυγνός</span>) 1 aoristo <span class=\"greek\">ἐστύγνασα</span></p>\n<p class=\"entry-text\">① estar em estado de intenso consternamento, ficar chocado, estar estarrecido (Ezk 26:16 [JZiegler ’52]; 27:35; 28:19; 32:10 <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>) assim talvez <span class=\"greek\">στυγνάσας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span>=chocado com a prescrição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:22</a> (v. 2a abaixo).</p>\n<p class=\"entry-text\">② ter aparência escura ou sombria, estar ou tornar-se sombrio, escuro (AcPlTh 35 [Aa 261, 10])</p>\n<p class=\"entry-text\">ⓐ de alguém cuja aparência manifesta tristeza ou abatimento (TestSol 1:4 L; Himerius, Or. [Ecl.] 3, 2; PGM 13, 177; 494; escólio a Aeschyl., Pers. 470; escólio a Soph., Ant. 526; escólio a Apollon. Rhod. 2, 862f; Macrembolites Eustathius 4, 1, 2 Hilberg 1876; Nicetas Eugen. 6, 286 H.) <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> diante de algo, assim talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:22</a> (mas v. 1 acima).</p>\n<p class=\"entry-text\">ⓑ da aparência do céu (v. <span class=\"greek\">στυγνός</span>: Heraclit. Sto. 39 p. 56, 18) carregado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:3</a> (Cat. Cod. Astr. XI/2 p. 179, 19 depende desta passagem).—DELG s.v. <span class=\"greek\">στυγέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυγνός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στυγνός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> sombrio, triste (assim desde Aeschyl.; X., An. 2, 6, 9. Também PSI 28, 1 <span class=\"greek\">στυγνοῦ</span> <span class=\"greek\">σκότους</span>; LXX; TestLevi 3:1; Jos., Ant. 19, 318) Hv 1, 2, 3 oposto a <span class=\"greek\">γελῶν</span> como em GJs 17:2. <span class=\"greek\">τί</span> ‹<span class=\"greek\">οὕ</span>›<span class=\"greek\">τως</span> <span class=\"greek\">στυγνὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κατηφής</span>, <span class=\"greek\">κύριε</span>; Por que tão triste e abatido, Senhor? AcPl Ha 7, 30.—DELG s.v. <span class=\"greek\">στύγεω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στῦλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στῦλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl., Hdt.+; inscrições, papiros, LXX, En; TestSol 25:8 B; ParJer 1:2; Jos., Ant. 13, 211; Just., D. 38, 1 e outras ocorrências; Mel., P. 84, 631; 88, 658. Sobre o acento [<span class=\"greek\">στύλο</span>] v. KLipsius, Gramm. Untersuchungen 1863 p. 43)</p>\n<p class=\"entry-text\">① parte de sustentação de uma estrutura, ordinariamente cilíndrica, pilar, coluna, literalmente <span class=\"greek\">στῦλοι</span> <span class=\"greek\">πυρός</span> (En 18:11; 21:7; singular Ex 13:21f; 14:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:1</a>. Em linguagem figurada (Philo, Migr. Abr. 124)</p>\n<p class=\"entry-text\">② pessoa ou comunidade reconhecida pela liderança espiritual, pilar, sustentáculo <span class=\"greek\">ποιήσω</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">στ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ναῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> farei dele uma coluna no templo de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:12</a> (<span class=\"greek\">στῦλοι</span> no templo 3 Km 7:3=Jos., Ant. 8, 77). Daí, figuradamente, dos líderes da igreja de Jerusalém: Tiago, Cefas, João <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:9</a> (cf. Eur., Iph. Taur. 57 <span class=\"greek\">στῦλοι</span> <span class=\"greek\">οἴκων</span> <span class=\"greek\">εἰσὶ</span> <span class=\"greek\">παῖδες</span> <span class=\"greek\">ἄρσενες</span>. Vi. Aesopi G 106 P. Esopo é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">κίων</span> [pilar] <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span>. V. CBarrett, Studia Paulina ’53, 1–19; RAnnand, ET 67, ’56, 178 [‘os marcos’ numa pista de corrida]). Em 1 Cl 5:2 o termo é aplicado aos apóstolos e a outros líderes da igreja primitiva.—A comunidade dos cristãos é <span class=\"greek\">στῦλος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἑδραίωμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> sustentáculo (<span class=\"greek\">στ</span>. também é usado neste sentido geral Sir 24:4; 36:24) e fundamento da verdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:15</a>.—DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύραξ, ακος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στύραξ</span>, <span class=\"greek\">ακος</span>, <span class=\"greek\">ὁ</span> (X., Pla.+; também TestSol 5:13) literalmente a ponta metálica na extremidade inferior da haste de uma lança, depois, por sinédoque, a haste, a própria lança; <span class=\"greek\">περὶ</span> <span class=\"greek\">στύρακα</span> MPol 16:1 como conjectura em lugar da leitura manuscrita <span class=\"greek\">περιστερὰ</span> <span class=\"greek\">καί</span>, que não é transmitida por Eus. (v. <span class=\"greek\">περιστερά</span>).—DELG 2 <span class=\"greek\">στύραξ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στωϊκός</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Στωϊκός</span> v. <span class=\"greek\">Στοϊκός</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0333-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύ</h1><div class=\"entry-meta\"><span>pronome pessoal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύ</span> (Hom.+) pronome pessoal da segunda pessoa <span class=\"greek\">σοῦ</span> (<span class=\"greek\">σου</span>), <span class=\"greek\">σοί</span> (<span class=\"greek\">σοι</span>), <span class=\"greek\">σέ</span> (<span class=\"greek\">σε</span>); plural <span class=\"greek\">ὑμεῖς</span>, <span class=\"greek\">ὑμῶν</span>, <span class=\"greek\">ὑμῖν</span>, <span class=\"greek\">ὑμᾶς</span>: tu, vós</p>\n<p class=\"entry-text\">ⓐ nominativo</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. em contraste com outra pessoa <span class=\"greek\">ἐγὼ</span> … <span class=\"greek\">σύ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:14</a>; 26:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:18</a>; v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:8</a>. <span class=\"greek\">σὺ</span> … <span class=\"greek\">ἕτερος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:3</a>. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ἄνθρωπος</span> … <span class=\"greek\">σύ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:10</a>. <span class=\"greek\">Μωϋσῆς</span> … <span class=\"greek\">σὺ</span> <span class=\"greek\">οὖν</span> 8:5. <span class=\"greek\">οὐδεὶς</span> … <span class=\"greek\">σύ</span> 3:2 e frequentemente. <span class=\"greek\">αὐτοὶ</span> … <span class=\"greek\">σύ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:11</a> (Ps 101:27). <span class=\"greek\">ἐγὼ</span> … <span class=\"greek\">ὑμεῖς</span> ou vice-versa (TestJob 1:5; Mel., P. 103, 789ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:34</a>, 36; 8:15, 22f; 13:15; 15:5 e outras ocorrências; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:12</a>. <span class=\"greek\">ὑμεῖς</span> … <span class=\"greek\">ἡμεῖς</span> ou vice-versa (ParJer 4:9; Just., D. 10, 1 e outras ocorrências) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:10abc</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:9</a>.—O contraste é evidente pelo contexto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:6</a>, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:3</a>. <span class=\"greek\">ὑμεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:48</a>; 6:9, 26b.—Sobre <span class=\"greek\">σὺ</span> <span class=\"greek\">λέγεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:3</a> v. <span class=\"greek\">λέγω</span> 2e.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. para dar ênfase antes de um vocativo <span class=\"greek\">σὺ</span> <span class=\"greek\">Βηθλεέμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a> (Mi 5:1). <span class=\"greek\">σὺ</span> <span class=\"greek\">παιδίον</span> (Lucian, Dial. Deor. 2, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.76\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:76</a>. <span class=\"greek\">σὺ</span> <span class=\"greek\">κύριε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:24</a> (PsSol 2:23; 17:4). <span class=\"greek\">σὺ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὦ</span> <span class=\"greek\">ἄνθρωπε</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:11</a>. <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">Φαρισαῖοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:39</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. usado com um substantivo ou particípio, pelo qual o pronome é definido mais precisamente <span class=\"greek\">σὺ</span> <span class=\"greek\">Ἰουδαῖος</span> <span class=\"greek\">ὤν</span> tu, como judeu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:14</a>. <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">πονηροὶ</span> <span class=\"greek\">ὄντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:11</a> (cf. ParJer 7:3 <span class=\"greek\">σὺ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαλῶν</span>).—Especialmente enfatizando o sujeito: <span class=\"greek\">σὺ</span> <span class=\"greek\">τρίς</span> <span class=\"greek\">με</span> <span class=\"greek\">ἀπαρνήσῃ</span> tu és precisamente aquele que me negará três vezes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:30</a>. <span class=\"greek\">δότε</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">φαγεῖν</span> vós mesmos deveis dar-lhes algo para comer = dai-lhes vós mesmos algum alimento Mft <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:16</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:6</a>; 17:8; 20:15. <span class=\"greek\">εὐλογημένη</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γυναιξίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:42</a>. <span class=\"greek\">σὺ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">παροικεῖς</span> 24:18. Assim frequentemente com formas de <span class=\"greek\">εἰμι</span> (TestAbr A 7 p. 84, 19 [Stone p. 16] <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span> … <span class=\"greek\">σὺ</span> <span class=\"greek\">εἶ</span>; A 16 p. 97, 26 [Stone p. 42] <span class=\"greek\">τίς</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">σύ</span>; A 17 p. 98, 21 [Stone p. 44] <span class=\"greek\">σὺ</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θάνατος</span>; TestJob 29:3 e outras ocorrências): <span class=\"greek\">σὺ</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">χριστός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:16</a>; <span class=\"greek\">σὺ</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">Πέτρος</span> versículo 18; <span class=\"greek\">σὺ</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span>; 27:11. <span class=\"greek\">καὶ</span> <span class=\"greek\">σύ</span> tu também 26:69, 73; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:19</a>; 22:58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a> (TestAbr B 4 p. 109, 10 [Stone p. 66]; TestJob 27:5; ParJer 7:9; Just., A II, 2, 17). <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑμεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a>; 15:3, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:10</a> (TestJob 27:7). <span class=\"greek\">σὺ</span> <span class=\"greek\">δέ</span> mas tu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.60\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:60</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:10</a> (Just., D. 1, 6 e outras ocorrências; Tat. 19, 3). <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:6</a> (TestJob 24:3; ApcMos 30).</p>\n<p class=\"entry-text\"><span class=\"greek\">δ</span>. acrescentado pleonasticamente a formas que são suficientemente claras por si mesmas (semitismo? V. B-D-F §277, 2; Mlt-H. 431f) <span class=\"greek\">σὺ</span> <span class=\"greek\">τί</span> <span class=\"greek\">λέγεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:68</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβεῖσθε</span> <span class=\"greek\">ὑμεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:5</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀνελεῖν</span> <span class=\"greek\">με</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">θέλεις</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:28</a> (Ex 2:14). <span class=\"greek\">ὑμεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13f</a>.</p>\n<p class=\"entry-text\">ⓑ casos oblíquos</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. As formas acentuadas são usadas nos casos oblíquos do singular quando se pretende dar ênfase ao pronome ou estabelecer um contraste <span class=\"greek\">σοῦ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:35</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">ῥίζαν</span> <span class=\"greek\">βαστάζεις</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">σέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:18</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">σέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:3</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. As formas acentuadas aparecem também sem ênfase especial quando usadas com preposições (B-D-F §279; Mlt-H. 180) <span class=\"greek\">ἐν</span> <span class=\"greek\">σοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:23</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:35</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">σοῦ</span> versículo 28. <span class=\"greek\">σὺν</span> <span class=\"greek\">σοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:35</a>, mas <span class=\"greek\">πρός</span> <span class=\"greek\">σε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:28</a>; 25:39 (cf. PsSol 5:8; v. <span class=\"greek\">ἐγώ</span>).</p>\n<p class=\"entry-text\">ⓒ <span class=\"greek\">σου</span> e <span class=\"greek\">ὑμῶν</span> como substitutos dos pronomes possessivos/adjetivais <span class=\"greek\">σός</span> e <span class=\"greek\">ὑμέτερος</span> (<span class=\"greek\">πάντες</span> <span class=\"greek\">σου</span> 4 [6] Esdr [POxy 1010]; bem como do genitivo dos reflexivos <span class=\"greek\">σεαυτοῦ</span> e <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">αὐτῶν</span>) vêm depois da palavra que modificam: <span class=\"greek\">τὴν</span> <span class=\"greek\">γυναῖκά</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>; <span class=\"greek\">τὸν</span> <span class=\"greek\">πόδα</span> <span class=\"greek\">σου</span> 4:6 (Ps 90:12); <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:8</a>; <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">ὑμῶν</span> 6:19; <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:4</a>. Ou antes da palavra que modificam (TestAbr A 16 p. 97, 1 [Stone p. 42] <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγριότητα</span>; B 6 p. 110, 13 [Stone p. 68] <span class=\"greek\">σου</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφθαλμοί</span>; TestJob 4:5 <span class=\"greek\">σου</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπάρχοντα</span>; JosAs 4:10; 15:9 e outras ocorrências; ApcMos 12): <span class=\"greek\">ἆρόν</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κλίνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:6</a>; <span class=\"greek\">ἀφέωνταί</span> <span class=\"greek\">σου</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἁμαρτίαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:48</a>; <span class=\"greek\">μηδείς</span> <span class=\"greek\">σου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νεότητος</span> <span class=\"greek\">καταφρονείτω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:12</a>. Ou entre o substantivo e o artigo (TestJob 42:5 <span class=\"greek\">οἱ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">σου</span> <span class=\"greek\">φίλοι</span>): <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">δεήσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:19</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">προκοπήν</span> versículo 25.—Sobre <span class=\"greek\">τί</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοί</span>; v. <span class=\"greek\">ἐγώ</span>, final; sobre <span class=\"greek\">τί</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σοί</span>; v. <span class=\"greek\">τίς</span> 1a<span class=\"greek\">β</span>ה—M-M.</p></section></article>"};
